import{_ as o}from"./chunks/architecture.Cs8uKTTN.js";import{_ as r,o as c,c as a,a2 as d}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"架構設計","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/dev-guide/architecture.md","filePath":"zh-HK/dev-guide/architecture.md","lastUpdated":1787473456000}'),t={name:"zh-HK/dev-guide/architecture.md"};function i(l,e,s,p,n,h){return c(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="架構設計" tabindex="-1">架構設計 <a class="header-anchor" href="#架構設計" aria-label="Permalink to &quot;架構設計&quot;">​</a></h1><p><img src="'+o+'" alt="Lertaro 架構圖"></p><h2 id="處理程序拆分" tabindex="-1">處理程序拆分 <a class="header-anchor" href="#處理程序拆分" aria-label="Permalink to &quot;處理程序拆分&quot;">​</a></h2><p>Lertaro 運行為三個獨立處理程序，按權限級別和生命週期有意拆分:</p><ul><li><strong><code>Lertaro.Service</code></strong> —— 一個以 <code>LocalSystem</code> 身份運行的 Windows 服務。它負責全部檔案索引工作:讀取 NTFS/ReFS 磁碟的 USN 日誌與 MFT、直接遍歷並監聽其他本地檔案系統(它們沒有日誌可讀)、掃描並快取網絡共享，並通過命名管道回答搜尋查詢。在 SYSTEM 級別運行意味着它可以讀取所有使用者帳戶都被允許看到的原始卷中繼資料，而不需要讓交互式的 App 處理程序獲得它本不需要的提升權限。</li><li><strong><code>Lertaro.App</code></strong> —— 使用者態、Session 級別的 WPF 應用:搜尋視窗、設定視窗、熱鍵處理、動作選單/QuickLook 介面都在這裏。它通過命名管道(<code>Core.Services</code> 裏的 <code>SearchService</code>/ <code>UsnServicePipeServer</code>)和 Service 通信，從不直接訪問磁碟索引。它自己也額外託管了一條按使用者區分的管道(<code>AppSearchPipeService</code>)，讓 <code>lff</code> 命令列伴侶工具(參見<a href="./../user-guide/cli.html">命令列搜尋</a>) 能複用 App 已經初始化好的搜尋狀態——已加載的別名/插件提供方、已配置的網絡盤索引——而不用一個獨立的用戶端處理程序自己重新初始化一遍。</li><li><strong><code>Lertaro.Service --hook</code></strong> —— 一個獨立的小處理程序，專門託管低層級全局鍵盤鉤子，這樣鉤子崩潰或者某個前臺應用行為異常都不會連累主 App 處理程序。它還會加載插件的視窗集成適配器，並在自己處理程序裏執行這些調用——見下文<a href="#插件在架構中的位置">插件在架構中的位置</a>。</li></ul><h2 id="共享的-core" tabindex="-1">共享的 Core <a class="header-anchor" href="#共享的-core" aria-label="Permalink to &quot;共享的 Core&quot;">​</a></h2><p><code>Core</code> 是一個被 Service 和 App 同時引用的類庫。它包含:</p><ul><li>搜尋引擎(<code>Core/SearchIndex/Fzf/*</code>)—— 一套仿照 <code>fzf</code> 命令列工具算法實現的模糊匹配引擎，配合一個查詢解析器(<code>SearchQueryParser</code>)處理盤符定向和路徑模式搜尋。</li><li>運行時索引(<code>Core/IndexV2/*</code>)—— 由 USN/MFT 讀取結果構建的記憶體映射列式快照格式，配合一個記憶體中的增量覆蓋層記錄快照之後的變更。</li><li>IPC 契約(<code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等)—— App 和 Service 兩邊完全共用同一份定義，保證雙方對線路格式的理解始終一致。</li><li><code>Logger</code> —— 寫入各處理程序獨立的日誌檔案(<code>service.log</code>、<code>app.log</code>、<code>hook.log</code>)，都可以在 App 的設定 → 運行狀態 日誌查看器裏讀取(但不是都能直接寫入)。</li></ul><h2 id="插件在架構中的位置" tabindex="-1">插件在架構中的位置 <a class="header-anchor" href="#插件在架構中的位置" aria-label="Permalink to &quot;插件在架構中的位置&quot;">​</a></h2><p>插件是引用 <code>PluginSdk</code> 的 <code>.dll</code> 程式集，由 App 進程加載(見<a href="./getting-started.html">快速上手</a>和<a href="./packaging.html">打包與發布</a>)。Lertaro 自帶內建插件作為一等公民示例——<code>Lertaro.Plugins.CoreExtensions</code>(內建檔案動作與 Shell 右鍵選單集成)、<code>Lertaro.Plugins.PinyinAlias</code>(中文檔案名拼音別名)以及 <code>Lertaro.Plugins.FlowLauncherBridge</code>(橋接 C#、Python 3.12、Node.js v20 LTS 及可執行檔案格式的第三方 Flow Launcher 插件並提供純淨隔離運行環境)——參見<a href="./examples.html">插件示例</a>了解原生插件的詳細走讀。</p><p>插件從不直接和 Service 通信;它們通過插件 SDK 參考裏記錄的接口和 App 交互，如果需要索引自訂目錄，則通過 <code>DirectoryIndexerService</code> 代為向 Service 轉發請求。</p><p>視窗集成類適配器是&quot;只在 App 裏跑&quot;這條規則的唯一例外: <a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a> 的實現會被再加載一份到 Hook 處理程序裏，它們的調用實際在 Hook 處理程序裏執行，而不是在 App 裏。這也是為什麼 Lertaro 能操作一個以系統管理員身份運行的檔案總管/檔案對話方塊/第三方檔案管理器視窗——即使 App 本身從來不提權:Windows 不允許低權限處理程序向高權限處理程序發送輸入，所以這類調用必須從一個和目標視窗權限級別相同的處理程序發起。</p>',12)])])}const m=r(t,[["render",i]]);export{g as __pageData,m as default};
